/* @autogenerated */
import { computed, Directive, effect, input } from '@angular/core';
import { BaseEditable } from './base-editable';
import { debounce as debounceBy, distinctUntilChanged, startWith, Subscription, timer } from 'rxjs';
import { SelectorProvider } from '@shared/data/selector-provider';
import { FormControl } from '@angular/forms';

@Directive({})
export abstract class SearchEditable<V, R> extends BaseEditable<R> {
  provider = input.required<SelectorProvider<V, R>>();
  /** Milisegundos de espera tras teclear antes de buscar. */
  debounce = input(250);
  search = new FormControl(null as any);

  /** La última búsqueda terminó sin resultados. */
  readonly noResults = computed(() => {
    const provider = this.provider();
    return !provider.searching() && !provider.error() && provider()?.length === 0;
  });

  private searchSubscription?: Subscription;
  private updateSubscription?: Subscription;
  private selectionSubscription?: Subscription;

  public constructor() {
    super();
    this.bind([this.search]);
    this.searchSubscription = this.search.valueChanges
      .pipe(
        debounceBy(() => timer(this.debounce())),
        distinctUntilChanged(),
      )
      .subscribe((text) => {
        if (typeof text === 'string') {
          this.provider().search(text);
        }
      });
    effect(() => this.search.patchValue(this.provider().selection()));
    effect(() => {
      const searching = this.provider().searching();
      setTimeout(() => {
        if (this.control.enabled) {
          this.pending.set(searching);
        }
      });
    });
  }

  get options() {
    return this.provider();
  }

  override ngOnDestroy(): void {
    this.updateSubscription?.unsubscribe();
    this.searchSubscription?.unsubscribe();
    this.selectionSubscription?.unsubscribe();
    super.ngOnDestroy();
  }

  /** Si la búsqueda o la selección falló, el mensaje se muestra como error del campo. */
  override feedbackErrorKey(): string | null {
    return this.provider().error() ? 'common.selector.error' : null;
  }

  searchOptions() {
    this.provider().search('');
  }

  optionSelected(option: any) {
    this.select(this.provider().value(option));
  }

  bindValueEffect() {
    effect(() => {
      const provider = this.provider();
      this.updateSubscription?.unsubscribe();
      setTimeout(() => {
        this.updateSubscription?.unsubscribe();
        // Parte del valor actual: reemitir el mismo valor (validación, pending) no vuelve a seleccionar ni borra las opciones
        this.updateSubscription = this.control.valueChanges
          .pipe(startWith(this.control.value), distinctUntilChanged())
          .subscribe((value) => provider.select(value));
      });
    });
  }

  blur() {
    const text = this.search.value;
    if (!text) {
      this.search.patchValue(null);
      this.select(null);
    } else if (typeof text === 'string') {
      //   const value = this.value();
      const provider = this.provider();
      const candidate = provider()?.find((item) => provider.display(item) === text);
      if (candidate) {
        this.select(provider.value(candidate));
      } else {
        this.search.patchValue(null);
        this.updateValue(null);
      }
    }
  }

  abstract select(value: R | null): void;

  compareObjects() {
    return (option1: R, option2: R) => this.compare(option1, option2);
  }

  displayItem() {
    return (item: V) => {
      return item ? this.provider().display(item) : '';
    };
  }

  compare(option1: R | null, option2: R | null) {
    return option1 !== null && option2 !== null && this.provider().equals(option1, option2);
  }
}
